1	//! Unified destruction pipeline.
2	//!
3	//! All "destroy" effects and state-based destruction flow through `try_destroy`,
4	//! which checks indestructible and regeneration before actually killing a permanent.
5	//! Sacrifice uses `sacrifice`, which bypasses both.
6	
7	use crate::cards::CardRegistry;
8	use crate::events::GameEvent;
9	use crate::ids::ObjectId;
10	use crate::state::{GameState, LogLevel};
11	use crate::types::{Keyword, Zone};
12	
13	/// Result of attempting to destroy a permanent.
14	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
15	pub enum DestroyResult {
16	    /// Permanent was destroyed (moved to graveyard).
17	    Died,
18	    /// Destruction prevented by indestructible (no state change).
19	    Indestructible,
20	    /// Destruction replaced by regeneration (state changed: tapped, damage cleared).
21	    Regenerated,
22	}
23	
24	/// Attempt to destroy a permanent.
25	///
26	/// Pipeline:
27	/// 1. Indestructible — prevents destruction entirely (no state change).
28	/// 2. Regeneration shields — replaces destruction (tap, remove damage, consume shield).
29	/// 3. Falls through — permanent is destroyed (moved to graveyard).
30	///
31	/// Called by destroy spells (Doom Blade, etc.) and by SBAs for lethal damage / deathtouch.
32	/// NOT called for 0-toughness deaths (rule 704.5f) — those are not destruction.
33	pub fn try_destroy(state: &mut GameState, id: ObjectId, registry: &CardRegistry) -> DestroyResult {
34	    // Indestructible prevents destruction.
35	    if state.has_keyword(id, Keyword::Indestructible, registry) {
36	        return DestroyResult::Indestructible;
37	    }
38	
39	    // Regeneration replaces destruction.
40	    let shields = state.get_object(id).map(|o| o.regeneration_shields).unwrap_or(0);
41	    if shields > 0 {
42	        regenerate(state, id);
43	        return DestroyResult::Regenerated;
44	    }
45	
46	    // Actually destroy.
47	    destroy(state, id, Some(registry));
48	    DestroyResult::Died
49	}
50	
51	/// Destroy a permanent, bypassing regeneration ("can't be regenerated").
52	/// Still respects indestructible.
